Qu'est-ce qu'un cas de base ?

```javascript
function factorial(n) {
  if (n <= 1) {
    return 1; // ← Ceci est quoi ?
  }
  return n * factorial(n - 1);
}
```

Que se passe-t-il si on oublie le cas de base ?

```javascript
function badRecursion(n) {
  console.log(n);
  return badRecursion(n - 1); // Pas de condition d'arrêt!
}

badRecursion(5); // ?
```

Quelle est la différence entre récursion linéaire et arborescente ?

```javascript
// Récursion linéaire
function linearFactorial(n) {
  if (n <= 1) return 1;
  return n * linearFactorial(n - 1); // 1 seul appel
}

// Récursion arborescente  
function fibonacci(n) {
  if (n <= 1) return n;
  return fibonacci(n - 1) + fibonacci(n - 2); // 2 appels
}
```

Quel est l'ordre d'exécution dans une pile d'appels récursifs ?

```javascript
function countdown(n) {
  if (n <= 0) {
    console.log('Fini!');
    return;
  }
  console.log('Avant:', n);
  countdown(n - 1);
  console.log('Après:', n);
}

countdown(3);
// Ordre d'affichage ?
```

Qu'est-ce que la mémoïsation ?

```javascript
const memo = {};

function fibonacciMemo(n) {
  if (n in memo) {
    return memo[n]; // ← Optimisation
  }

  if (n <= 1) return n;

  memo[n] = fibonacciMemo(n - 1) + fibonacciMemo(n - 2);
  return memo[n];
}
```

