Comment tracer l'exécution d'une fonction récursive ?

```javascript
function factorial(n, depth = 0) {
  const indent = '  '.repeat(depth);
  console.log(`${indent}→ factorial(${n})`);

  if (n <= 1) {
    console.log(`${indent}← retourne 1`);
    return 1;
  }

  const result = n * factorial(n - 1, depth + 1);
  console.log(`${indent}← retourne ${result}`);
  return result;
}
```

