Comment éviter les recalculs en récursion ?

```javascript
// Sans mémoïsation - recalcule fibonacci(3) plusieurs fois
function fibSlow(n) {
  if (n <= 1) return n;
  return fibSlow(n - 1) + fibSlow(n - 2);
}

// Avec mémoïsation - calcule fibonacci(3) une seule fois
function fibFast(n, cache = {}) {
  if (n in cache) return cache[n];
  if (n <= 1) return n;
  cache[n] = fibFast(n - 1, cache) + fibFast(n - 2, cache);
  return cache[n];
}
```

Quelle est la différence entre récursion directe et indirecte ?

```javascript
// Récursion directe
function directRecursion(n) {
  if (n <= 0) return;
  directRecursion(n - 1); // S'appelle elle-même
}

// Récursion indirecte
function functionA(n) {
  if (n <= 0) return;
  functionB(n - 1); // Appelle functionB
}

function functionB(n) {
  if (n <= 0) return;
  functionA(n - 1); // Qui rappelle functionA
}
```

Comment convertir une récursion en itération ?

```javascript
// Version récursive
function factorialRecursive(n) {
  if (n <= 1) return 1;
  return n * factorialRecursive(n - 1);
}

// Version itérative équivalente
function factorialIterative(n) {
  let result = 1;
  for (let i = 2; i <= n; i++) {
    result *= i;
  }
  return result;
}
```

Que faut-il vérifier avant d'implémenter une solution récursive ?

```javascript
// Problème: Calculer la somme d'un tableau
// Est-ce que cela se décompose bien récursivement ?

function sumArray(arr) {
  // Cas de base
  if (arr.length === 0) return 0;
  if (arr.length === 1) return arr[0];

  // Cas récursif - diviser le problème
  return arr[0] + sumArray(arr.slice(1));
}
```
